import com.exsited.sdk.Dto;
import com.exsited.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse<Dto> response = client.communications().sendEmail(
        Map.of(
                "invoice", "INV-0001",
                "to", List.of("jane@example.com"),
                "subject", "Your invoice",
                "body", "Hello Jane, here is your invoice."));
System.out.println(response.getMap());
